/** Preserve the approved native special-page templates and their business content. */
function mrseo_pue_setup($route){
 if(mrseo_locale()!=='uk'||mrseo_slug()!==$route||!in_array($route,array('horoshop','about','portfolio','contact','privacy'),true))return;
 add_action('wp_enqueue_scripts',static function()use($route){
  wp_enqueue_style('mrseo-pue',get_template_directory_uri().'/assets/premium-ua-editorial.css',array('mrseo-style'),'1.0.0');
  if($route!=='privacy')wp_enqueue_script('mrseo-pue',get_template_directory_uri().'/assets/premium-ua-editorial.js',array(),'1.0.0',true);
 },100);
}
function mrseo_pue_marker($route){if(mrseo_locale()==='uk'&&mrseo_slug()===$route)echo '<span class="pue-marker" data-pue-route="'.esc_attr($route).'" hidden></span>';}
